What does this program print?

```zig
const std = @import("std");

const Counter = struct {
    n: u32 = 0,
    fn bumpCopy(self: Counter) u32 {
        var copy = self;
        copy.n += 10;
        return copy.n;
    }
    fn bump(self: *Counter) void {
        self.n += 1;
    }
};

pub fn main() void {
    var a: Counter = .{};
    var b = a;
    a.bump();
    b.bump();
    b.bump();
    const r = a.bumpCopy();
    std.debug.print("{d} {d} {d}\n", .{ a.n, b.n, r });
}
```

