What does this program print?

```zig
const std = @import("std");

const Token = union(enum) {
    number: i64,
    plus,
    minus,
    word: []const u8,
};

pub fn main() void {
    const tokens = [_]Token{ .{ .number = 7 }, .plus, .{ .word = "x" }, .minus, .{ .number = 2 } };
    var total: i64 = 0;
    var sign: i64 = 1;
    for (tokens) |t| switch (t) {
        .number => |n| total += sign * n,
        .plus => sign = 1,
        .minus => sign = -1,
        .word => |w| std.debug.print("skip {s} ", .{w}),
    };
    std.debug.print("{d}\n", .{total});
}
```
